import React, { useEffect, useRef } from "react";
import "./service.css";

export default function Service() {
  const ref = useRef(null);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;

    const obs = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            el.classList.add("is-visible");
            obs.unobserve(el);
          }
        });
      },
      { threshold: 0.12 },
    );

    obs.observe(el);
    return () => obs.disconnect();
  }, []);

  return (
    <section
      id="services"
      ref={ref}
      className="testimonials animate animate-slide-left"
    >
      <h1 className="testimonials-title">Experience</h1>

      <div className="testimonials-grid">
        <div className="testimonial-card">
          <h3>🏠 Civil</h3>
          <p>
            Site Supervision & Execution
            <br /> Quantity Surveying
            <br /> Contractor Coordination
            <br /> Quality Control & Safety Monitoring
          </p>
        </div>

        <div className="testimonial-card">
          <h3>📐 Architect</h3>
          <p>
            AutoCAD Drafting (Floor Plans, Elevations, Sections)
            <br />
            Structural Layout Drawings
            <br />
            Approval Drawings
          </p>
        </div>

        <div className="testimonial-card">
          <h3>🛋️ Interior Design</h3>
          <p>
            3D Elevation Design
            <br />
            Interior & Exterior Rendering
            <br />
            Walkthrough Visualization
            <br />
            SketchUp Modeling
            <br />
            VRay Rendering
          </p>
          <br />
        </div>

        <div className="testimonial-card">
          <h3>🛋️ 3D Design</h3>
          <p>
            3D Elevation Design
            <br />
            Interior & Exterior Rendering
            <br />
            Walkthrough Visualization
            <br />
            SketchUp Modeling
            <br />
            VRay Rendering
          </p>
          <br />
        </div>
      </div>
    </section>
  );
}
